def setZeroes(matrix: list[list[int]]) -> None:
    m, n = len(matrix), len(matrix[0])
    col0 = False
    for i in range(m):
        if matrix[i][0] == 0:
            col0 = True
        for j in range(1, n):
            if matrix[i][j] == 0:
                matrix[i][0] = 0
