void nextPermutation(vector<int>& nums) {
    int n = nums.size(), k = n - 2;
    while (k >= 0 && nums[k] >= nums[k + 1]) k--;
    if (k < 0) {
        reverse(nums.begin(), nums.end());
    } else {
        int l = n - 1;
        while (l > k && nums[l] <= nums[k]) l--;
        swap(nums[k], nums[l]);
        reverse(nums.begin() + k + 1, nums.end());
    }
}

