    n = len(nums)
    k = n - 2
    while k >= 0 and nums[k] >= nums[k + 1]:
        k -= 1
    if k < 0:
        nums.reverse()
    else:
        l = n - 1
        while l > k and nums[l] <= nums[k]:
            l -= 1
        nums[k], nums[l] = nums[l], nums[k]
        nums[k + 1:] = reversed(nums[k + 1:])

