vector<int> repeatedNumber(const vector<int>& A) {
    long long n = A.size();
    long long s1 = (n * (n + 1)) / 2;
    long long s2 = (n * (n + 1) * (2 * n + 1)) / 6;
    long long sum = 0, sq_sum = 0;
    for (int x : A) {
        sum += x;
        sq_sum += (long long)x * x;
    }
    long long diff_sum = sum - s1; // Y - X
    long long diff_sq = sq_sum - s2; // Y^2 - X^2
    long long sum_xy = diff_sq / diff_sum; // Y + X
    int y = (diff_sum + sum_xy) / 2; // Repeating
    int x = sum_xy - y; // Missing
    return {y, x};
}

