ListNode* rotateRight(ListNode* head, int k) {
    if (head == nullptr || head->next == nullptr || k == 0) return head;
    int len = 1;
    ListNode* curr = head;
    while (curr->next != nullptr) {
        curr = curr->next;
        len++;
    }
    curr->next = head; // Make it circular
    k = k % len;
    int steps = len - k;
    while (steps > 0) {
        curr = curr->next;
        steps--;
    }
    head = curr->next;
    curr->next = nullptr; // Break the cycle
    return head;
}

