def fractionalKnapsack(W: int, arr: list[tuple[int, int]]) -> float:
    # arr elements: (value, weight)
    arr.sort(key=lambda x: x[0] / x[1], reverse=True)
    total_val = 0.0
    for val, wt in arr:
        if W >= wt:
            total_val += val
            W -= wt
        else:
            total_val += val * (W / wt)
            break
    return total_val

