    res = []
    def isPalindrome(sub):
        return sub == sub[::-1]

    def helper(idx, path):
        if idx == len(s):
            res.append(list(path))
            return
        for i in range(idx, len(s)):
            substring = s[idx:i+1]
            if isPalindrome(substring):
