def solveSudoku(board: list[list[str]]) -> None:
    def isValid(r, c, val):
        for i in range(9):
            if board[r][i] == val:
                return False
            if board[i][c] == val:
                return False
            if board[3 * (r // 3) + i // 3][3 * (c // 3) + i % 3] == val:
                return False
        return True

    def solve():
        for i in range(9):
            for j in range(9):
                if board[i][j] == ".":
                    for char in "123456789":
                        if isValid(i, j, char):
                            board[i][j] = char
                            if solve():
                                return True
                            board[i][j] = "."
                    return False
        return True

    solve()

