void findPaths(int i, int j, vector<vector<int>>& m, int n, string path,
                vector<string>& res, vector<vector<bool>>& vis) {
    if (i == n - 1 && j == n - 1) {
        res.push_back(path);
        return;
    }
    // Alphabetical order: D, L, R, U
    int di[] = {1, 0, 0, -1};
    int dj[] = {0, -1, 1, 0};
    char dir[] = {'D', 'L', 'R', 'U'};
    for (int k = 0; k < 4; k++) {
        int ni = i + di[k];
        int nj = j + dj[k];
        if (ni >= 0 && ni < n && nj >= 0 && nj < n && !vis[ni][nj] && m[ni][nj] == 1) {
            vis[i][j] = true;
            findPaths(ni, nj, m, n, path + dir[k], res, vis);
            vis[i][j] = false; // Backtrack
        }
    }
}

