def verticalTraversal(root: Optional[TreeNode]) -> list[list[int]]:
    if root is None:
        return []
    from collections import deque, defaultdict
    m = defaultdict(list) # col -> list of (row, val)
    q = deque([(root, 0, 0)])
    while q:
        node, col, row = q.popleft()
        m[col].append((row, node.val))
        if node.left is not None:
            q.append((node.left, col - 1, row + 1))
        if node.right is not None:
            q.append((node.right, col + 1, row + 1))

    res = []
    for col in sorted(m.keys()):
        # Sort by row first, then by value
        sorted_nodes = sorted(m[col], key=lambda x: (x[0], x[1]))
        res.append([val for row, val in sorted_nodes])
    return res

