    # adj[u] elements: [v, weight]
    import heapq
    dist = [float('inf')] * V
    dist[S] = 0
    pq = [(0, S)] # heap stores: (distance, vertex)
    while pq:
        d, curr = heapq.heappop(pq)
        if d > dist[curr]:
