    vis = [False] * V
    pq = [(0, 0)] # heap stores: (weight, node)
    mst_sum = 0
    while pq:
        wt, curr = heapq.heappop(pq)
        if vis[curr]:
            continue
        vis[curr] = True
        mst_sum += wt
        for neighbor, edge_wt in adj[curr]:
            if not vis[neighbor]:
                heapq.heappush(pq, (edge_wt, neighbor))
    return mst_sum

