def kosaraju(V: int, adj: list[list[int]]) -> int:
    vis = [False] * V
    st = []
    def dfsStore(node):
        vis[node] = True
        for neighbor in adj[node]:
            if not vis[neighbor]:
                dfsStore(neighbor)
        st.append(node)

    for i in range(V):
        if not vis[i]:
            dfsStore(i)

    # Transpose
    adjT = [[] for _ in range(V)]
    for u in range(V):
        vis[u] = False
        for v in adj[u]:
            adjT[v].append(u)

    def dfsTranspose(node):
        vis[node] = True
        for neighbor in adjT[node]:
            if not vis[neighbor]:
                dfsTranspose(neighbor)

    scc = 0
    while st:
        node = st.pop()
        if not vis[node]:
            scc += 1
            dfsTranspose(node)
    return scc

