def lengthOfLIS(nums: list[int]) -> int:
    import bisect
    temp = []
    for x in nums:
        idx = bisect.bisect_left(temp, x)
        if idx == len(temp):
            temp.append(x)
        else:
            temp[idx] = x
    return len(temp)

