    for (int j = 1; j <= k; j++) dp[1][j] = j; // 1 egg needs j checks
    for (int i = 1; i <= n; i++) dp[i][1] = 1; // 1 floor needs 1 check

    for (int i = 2; i <= n; i++) {
        for (int j = 2; j <= k; j++) {
            dp[i][j] = INT_MAX;
            for (int x = 1; x <= j; x++) {
                int attempts = 1 + max(dp[i - 1][x - 1], dp[i][j - x]);
                dp[i][j] = min(dp[i][j], attempts);
            }
        }
    }
    return dp[n][k];
}

