def getMaxPathSum(matrix: list[list[int]]) -> int:
    m, n = len(matrix), len(matrix[0])
    prev = list(matrix[0])
    for i in range(1, m):
        curr = [0] * n
        for j in range(n):
            left_diag = prev[j - 1] if j > 0 else float('-inf')
            right_diag = prev[j + 1] if j + 1 < n else float('-inf')
            top = prev[j]
            curr[j] = matrix[i][j] + max(top, left_diag, right_diag)
        prev = list(curr)
    return max(prev)

ListNode* reverseList(ListNode* head) {
    ListNode* prev = nullptr;
    ListNode* curr = head;
    while (curr) {
        ListNode* nextTemp = curr->next; // Save next link
        curr->next = prev;              // Reverse pointer
        prev = curr;                    // Move prev up
        curr = nextTemp;                // Move curr up
    }
    return prev;
}

