    while(rem){
        if(pos.count(rem)){
            ans.insert(pos[rem],"(");
            ans+=')';
            break;
        }

        pos[rem]=ans.size();

        rem*=10;
        ans+=char('0'+rem/d);
        rem%=d;
    }

    return ans;
}

