    vector<int> base=sieve(sqrt(R)+1);
    vector<bool> prime(R-L+1,true);

    if(L==1) prime[0]=false;

    for(ll p:base){
        ll cur=max(p*p,((L+p-1)/p)*p);

        for(ll j=cur;j<=R;j+=p)
            prime[j-L]=false;
    }

    vector<ll> ans;

    for(ll i=L;i<=R;i++){
        if(prime[i-L])
            ans.push_back(i);
    }

    return ans;
}

